`timescale 1ns / 1ps

// This testbench simulates the BGT radar's SPI interface and sends over 768 precomputed ADC values from adc.mem, 
// generated by the python file "generate-adc.py"
// The code passes the tests for angle and range calculation for one frame.
module testbench;

    reg clk;
    reg rst;
    reg start;
    
    reg MISO;
    reg IRQ;
    
    wire SCLK;
    wire MOSI;
    wire SRST;
    wire CS_N;
    
    reg out_ready;
    
    wire signed [17:0] alpha;
    wire signed [17:0] beta;
    wire [23:0] range;
    wire out_valid;
    
    localparam N = 256;
    
    top_io_buffer # (
        .N(N),
        .FIRST_BIN(6),
        .FRAME_DELAY(5000)
    ) UUT (
        .clk(clk),
        .rst(rst),
        .start(start),
        
        .MISO(MISO),
        .IRQ(IRQ),
        
        .SCLK(SCLK),
        .MOSI(MOSI),
        .SRST(SRST),
        .CS_N(CS_N),
        
        .out_ready(out_ready),
        
        .alpha(alpha),
        .beta(beta),
        .range_calc(range),
        .out_valid(out_valid)
    );
    
    reg [11:0] adc_samples[0:(N * 3) - 1];
    
    localparam signed [17:0] EXPECTED_ALPHA = 18'sd8530;
    localparam signed [17:0] EXPECTED_BETA = -18'sd11826;
    localparam [23:0] EXPECTED_RANGE = 24'd1500000;
    
    initial begin
        clk = 0;
    end
    
    always #5 clk = ~clk;
    
    initial begin
        $readmemh("adc.mem", adc_samples);
    end
    
    task send_adc_sample;
        input [11:0] sample;
        integer bit_index;
        
        begin
            for(bit_index = 11; bit_index >= 0; bit_index = bit_index - 1) begin
                MISO = sample[bit_index];
                @(posedge SCLK);
                @(negedge SCLK);
            end
        end
    endtask
    
    
    integer sample_index;
    initial begin
        
        rst = 1;
        start = 0;
        MISO = 0;
        IRQ = 0;
        out_ready = 0;
        
        repeat(10) @ (posedge clk);
        rst = 0;
        repeat(5) @ (posedge clk);
        start = 1;
        @ (posedge clk)
        start = 0;
        
        wait(UUT.bgt_driver.state == 4'd5);
        repeat(10) @ (posedge clk);
        IRQ = 1;
        @ (posedge clk);
        IRQ = 0;
        
        wait (UUT.bgt_driver.state == 4'd6);
        
        for(sample_index = 0; sample_index < N * 3; sample_index = sample_index + 1) begin
            send_adc_sample(adc_samples[sample_index]);
        end
        
        MISO = 0;
        
        wait(out_valid);
        
        if($signed(alpha) != EXPECTED_ALPHA) begin
            $fatal(1, "Alpha: %0d does not match expected value of %0d", $signed(alpha), $signed(EXPECTED_ALPHA));
        end
        
        if($signed(beta) != EXPECTED_BETA) begin
            $fatal(1, "Beta: %0d does not match expected value of %0d", $signed(beta), $signed(EXPECTED_BETA));
        end
        
        if(range != EXPECTED_RANGE) begin
            $fatal(1, "Range: %0d does not match expected value of %0d", range, EXPECTED_RANGE);
        end
        
        $display("Passed tests");
        $display("alpha = %0d,   Expected: %0d", $signed(alpha), $signed(EXPECTED_ALPHA));
        $display("beta  = %0d,   Expected: %0d", $signed(beta), $signed(EXPECTED_BETA));
        $display("range = %0d,   Expected: %0d", range, EXPECTED_RANGE);
        
        out_ready = 1;
        @(posedge clk);
        
        $finish;
        
    end
            
endmodule